-- FND-04 / F1 design: autogenerated username = 'user_' + 8 chars from [a-z0-9] (was md5 hex, [0-9a-f] only).
create or replace function public.handle_new_user() returns trigger
  language plpgsql security definer set search_path = ''
as $$
begin
  loop
    begin
      insert into public.profiles (id, username)
      values (
        new.id,
        'user_' || (
          select string_agg(substr('abcdefghijklmnopqrstuvwxyz0123456789', 1 + floor(random() * 36)::int, 1), '')
          from generate_series(1, 8)
        )
      );
      return new;
    exception when unique_violation then
      -- username collision: try another one
    end;
  end loop;
end;
$$;
